import { cloneSemanticTree, HiddenDomProjector, parseSemanticBuffer } from '../semantic';
import type {
  AssetLoadResult,
  BridgeFontRegistration,
  BridgeFontStackRegistration,
  BridgeLoaderInfo,
  BridgeRuntime,
  OpenCanvasApi,
  SemanticNode,
  UiModule,
  CoreModule,
} from '../core-types';
import type { BridgeInteractionState } from './local-types';
import { resetBridgeLogs } from './utils/assets';
import { normalizeBackendType, handleToBigInt } from './utils/encoding';
import { executeCommandBuffer, extractCommandBuffer, extractSemanticBuffer, writeBytesToHeap } from './utils/heap';
import { setActiveRenderer } from './utils/backends';
import { getCanvasSizeSource, readCanvasLogicalSize } from './events';
import { getBridgeAssetUrl, getBuiltInBridgeFont } from './font-catalog';

const DEFAULT_LOGICAL_WIDTH = 320;
const DEFAULT_LOGICAL_HEIGHT = 220;
const UI_EVENT_POINTER_ENTER = 4;
const UI_EVENT_POINTER_LEAVE = 5;
const svgTextDecoder = new TextDecoder();

interface BitmapLike {
  readonly width: number;
  readonly height: number;
  close?(): void;
}

function createDecodeCanvas(width: number, height: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

async function decodeBlobToBitmap(blob: Blob): Promise<ImageBitmap> {
  if (createImageBitmap === undefined) {
    throw new Error('createImageBitmap is unavailable for texture decoding.');
  }
  return await createImageBitmap(blob);
}

function extractBitmapRgba(bitmap: CanvasImageSource & BitmapLike): Uint8Array {
  const canvas = createDecodeCanvas(bitmap.width, bitmap.height);
  const context = canvas.getContext('2d', { willReadFrequently: true });
  if (context === null) {
    throw new Error('Failed to allocate a 2D canvas for texture decoding.');
  }
  context.clearRect(0, 0, bitmap.width, bitmap.height);
  context.drawImage(bitmap, 0, 0);
  const imageData = context.getImageData(0, 0, bitmap.width, bitmap.height);
  return new Uint8Array(
    imageData.data.buffer.slice(
      imageData.data.byteOffset,
      imageData.data.byteOffset + imageData.data.byteLength,
    ),
  );
}

function parseSvgLength(value: string | null): number | null {
  if (value === null) {
    return null;
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return null;
  }
  const match = /^([+-]?(?:\d+\.?\d*|\.\d+))/.exec(trimmed);
  const numericPrefix = match?.[1];
  if (numericPrefix === undefined) {
    return null;
  }
  const parsed = Number.parseFloat(numericPrefix);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function parseSvgViewBox(value: string | null): AssetLoadResult | null {
  if (value === null) {
    return null;
  }
  const parts = value
    .trim()
    .split(/[\s,]+/)
    .map((entry) => Number.parseFloat(entry))
    .filter((entry) => Number.isFinite(entry));
  if (parts.length !== 4) {
    return null;
  }
  const width = parts[2];
  const height = parts[3];
  if (width === undefined || height === undefined) {
    return null;
  }
  if (width <= 0 || height <= 0) {
    return null;
  }
  return { width, height };
}

function parseSvgIntrinsicSize(bytes: Uint8Array): AssetLoadResult {
  const markup = svgTextDecoder.decode(bytes);
  const documentRoot = new DOMParser().parseFromString(markup, 'image/svg+xml').documentElement;
  const width = parseSvgLength(documentRoot.getAttribute('width'));
  const height = parseSvgLength(documentRoot.getAttribute('height'));
  if (width !== null && height !== null) {
    return { width, height };
  }
  const viewBox = parseSvgViewBox(documentRoot.getAttribute('viewBox'));
  if (viewBox !== null) {
    return viewBox;
  }
  return { width: 1, height: 1 };
}

export function createBridgeRuntime(
  core: CoreModule,
  ui: UiModule,
  canvas: HTMLCanvasElement,
  interactionState: BridgeInteractionState,
  loaderInfo: BridgeLoaderInfo,
): { runtime: BridgeRuntime; destroy(): void } {
  const projector = new HiddenDomProjector(canvas);
  let logicalWidth = DEFAULT_LOGICAL_WIDTH;
  let logicalHeight = DEFAULT_LOGICAL_HEIGHT;
  let semanticTree: SemanticNode[] = [];
  let needsCommit = false;
  let appFrameHandler: ((timestampMs: number) => void) | null = null;
  let frameRequester: (() => void) | null = null;
  const loadedFonts = new Map<number, string>();
  const fontFallbacks = new Map<number, number[]>();
  const lazyFontSources = new Map<number, string>();
  const pendingFontLoads = new Map<number, Promise<void>>();
  const loadedSvgs = new Map<number, string>();
  const loadedTextures = new Map<number, string>();

  const registerFontBytes = (fontId: number, bytes: Uint8Array): void => {
    const coreBytes = writeBytesToHeap(core, bytes);
    const uiBytes = writeBytesToHeap(ui, bytes);
    try {
      core._ed_register_font(fontId, coreBytes.ptr, coreBytes.len);
      ui._ui_register_font(fontId, uiBytes.ptr, uiBytes.len);
      ui._ui_font_loaded(fontId);
    } finally {
      coreBytes.dispose();
      uiBytes.dispose();
    }
  };

  const fetchFontBytes = async (url: string, replay = false): Promise<Uint8Array> => {
    const response = await fetch(url);
    if (!response.ok) {
      const verb = replay ? 'refetch' : 'fetch';
      throw new Error(`Failed to ${verb} font ${url}: ${String(response.status)}`);
    }
    return new Uint8Array(await response.arrayBuffer());
  };

  const applyFontFallbacks = (fontId: number, fallbackIds: readonly number[]): void => {
    fontFallbacks.set(fontId, [...fallbackIds]);
    for (const fallbackId of fallbackIds) {
      ui._ui_register_font_fallback(fontId, fallbackId);
    }
  };

  const registerSingleFontFallback = (fontId: number, fallbackFontId: number): void => {
    const existingFallbacks = fontFallbacks.get(fontId) ?? [];
    if (!existingFallbacks.includes(fallbackFontId)) {
      fontFallbacks.set(fontId, [...existingFallbacks, fallbackFontId]);
    }
    ui._ui_register_font_fallback(fontId, fallbackFontId);
  };

  const ensureRegisteredFont = async (
    fontId: number,
    url: string,
    fallbackIds: readonly number[] = [],
  ): Promise<void> => {
    const pending = pendingFontLoads.get(fontId);
    if (pending !== undefined) {
      await pending;
      return;
    }
    const request = runtime.registerFont(
      fallbackIds.length > 0
        ? {
          id: fontId,
          url,
          fallbackIds,
        }
        : {
          id: fontId,
          url,
        },
    ).finally(() => {
      pendingFontLoads.delete(fontId);
    });
    pendingFontLoads.set(fontId, request);
    await request;
  };

  const ensureFontWithFallbacks = async (fontId: number, visited = new Set<number>()): Promise<void> => {
    if (visited.has(fontId)) {
      return;
    }
    visited.add(fontId);
    if (!loadedFonts.has(fontId)) {
      const lazyUrl = lazyFontSources.get(fontId);
      if (lazyUrl !== undefined) {
        await ensureRegisteredFont(fontId, lazyUrl);
      } else {
        const builtInFont = getBuiltInBridgeFont(fontId);
        if (builtInFont !== undefined) {
          await ensureRegisteredFont(
            builtInFont.id,
            getBridgeAssetUrl(builtInFont.assetFile),
            builtInFont.fallbackIds,
          );
        }
      }
    }
    const fallbackIds = fontFallbacks.get(fontId) ?? [];
    await Promise.all(fallbackIds.map((fallbackId) => ensureFontWithFallbacks(fallbackId, visited)));
  };

  const openCanvasApi: OpenCanvasApi = {
    getSemanticTree: () => cloneSemanticTree(semanticTree),
    getBoundingBox: (handle: string) => {
      const node = semanticTree.find((entry) => entry.handle === handle);
      return node === undefined ? null : { ...node.bounds };
    },
  };

  const syncSemanticState = (): void => {
    semanticTree = parseSemanticBuffer(extractSemanticBuffer(ui));
    for (const node of semanticTree) {
      if (node.roleName !== 'textbox') {
        continue;
      }
      if (interactionState.textByHandle[node.handle] !== undefined) {
        continue;
      }
      if (node.label.length === 0) {
        continue;
      }
      interactionState.textByHandle[node.handle] = node.label;
    }
    const activeTextHandle = interactionState.getActiveTextHandle();
    const activeHandleKey = activeTextHandle?.toString() ?? null;
    projector.update(
      semanticTree,
      interactionState.textByHandle,
      interactionState.isActiveTextInputFocused() ? activeHandleKey : null,
    );
    window.__bridgeSemanticTree = cloneSemanticTree(semanticTree);
  };

  const dispatchAppPointerEvent = (eventType: number, handle: bigint, x: number, y: number, modifiers = 0): void => {
    if (handle === 0n) {
      return;
    }
    window.__effindomCallbacks?.onPointerEventWithCoords?.(eventType, handle, x, y, modifiers);
  };

  const isLastPointerStillOverCanvas = (): boolean => {
    const { x, y } = interactionState.getLastPointerClientPosition();
    if (x === null || y === null) {
      return false;
    }
    const rect = canvas.getBoundingClientRect();
    return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
  };

  const syncAppPointerHover = (): void => {
    const { x, y } = interactionState.getLastPointerPosition();
    const previousHandle = interactionState.getLastInteractivePointerHandle();
    const capturedHandle = interactionState.getCapturedPointerHandle();
    if (capturedHandle !== null) {
      if (previousHandle === capturedHandle) {
        return;
      }
      if (previousHandle !== null) {
        dispatchAppPointerEvent(UI_EVENT_POINTER_LEAVE, previousHandle, x, y);
      }
      interactionState.setLastInteractivePointerHandle(capturedHandle);
      dispatchAppPointerEvent(UI_EVENT_POINTER_ENTER, capturedHandle, x, y);
      return;
    }
    const pointerInsideCanvas = interactionState.isPointerInsideCanvas() || isLastPointerStillOverCanvas();
    if (!pointerInsideCanvas) {
      if (previousHandle !== null) {
        interactionState.setLastInteractivePointerHandle(null);
        dispatchAppPointerEvent(UI_EVENT_POINTER_LEAVE, previousHandle, x, y);
      }
      return;
    }

    const hitHandle = handleToBigInt(core._ed_hit_test(x, y));
    const currentHandle = hitHandle === 0n ? null : hitHandle;
    if (currentHandle === previousHandle) {
      return;
    }
    if (previousHandle !== null) {
      dispatchAppPointerEvent(UI_EVENT_POINTER_LEAVE, previousHandle, x, y);
    }
    interactionState.setLastInteractivePointerHandle(currentHandle);
    if (currentHandle !== null) {
      dispatchAppPointerEvent(UI_EVENT_POINTER_ENTER, currentHandle, x, y);
    }
  };

  window.__OPEN_CANVAS_API__ = openCanvasApi;

  const updateCanvasSize = (): void => {
    const dpr = Math.max(1, window.devicePixelRatio || 1);
    const size = readCanvasLogicalSize(canvas);
    logicalWidth = size.width;
    logicalHeight = size.height;
    const physicalWidth = Math.round(logicalWidth * dpr);
    const physicalHeight = Math.round(logicalHeight * dpr);

    canvas.style.width = `${String(logicalWidth)}px`;
    canvas.style.height = `${String(logicalHeight)}px`;
    if (physicalWidth !== canvas.width || physicalHeight !== canvas.height) {
      canvas.width = physicalWidth;
      canvas.height = physicalHeight;
    }

    projector.syncSize(logicalWidth, logicalHeight);
    core._ed_resize(physicalWidth, physicalHeight, dpr);
    ui._ui_resize_window(logicalWidth, logicalHeight);
    syncSemanticState();
    setActiveRenderer(loaderInfo, normalizeBackendType(core._ed_get_backend_type()));
  };

  const runtime: BridgeRuntime = {
    core,
    ui,
    canvas,
    logs: interactionState.logs,
    updateCanvasSize,
    extractCommandBuffer: () => extractCommandBuffer(ui),
    executeCommandBuffer: (words: Uint32Array) => {
      executeCommandBuffer(core, words);
    },
    syncCommandBufferToCore: () => {
      const words = extractCommandBuffer(ui);
      executeCommandBuffer(core, words);
      syncSemanticState();
      syncAppPointerHover();
      return words;
    },
    flushPendingCommit: () => {
      if (!needsCommit && !interactionState.hasPendingTextMutations()) {
        return null;
      }
      if (interactionState.hasPendingTextMutations()) {
        if (needsCommit) {
          needsCommit = false;
          runtime.syncCommandBufferToCore();
        }
        if (interactionState.materializePendingTextMutations()) {
          ui._ui_commit_frame();
          needsCommit = true;
        }
      }
      if (!needsCommit) {
        return null;
      }
      needsCommit = false;
      return runtime.syncCommandBufferToCore();
    },
    hasPendingCommit: () => needsCommit || interactionState.hasPendingTextMutations(),
    commitFrame: () => {
      if (interactionState.hasPendingTextMutations()) {
        if (needsCommit) {
          runtime.flushPendingCommit();
        }
        if (interactionState.materializePendingTextMutations()) {
          ui._ui_commit_frame();
          needsCommit = true;
          frameRequester?.();
          return;
        }
      }
      // UI command buffers are incremental. If the app commits again before the
      // render loop flushes the previous buffer, sync the older delta now so it
      // is not overwritten by the new commit.
      if (needsCommit) {
        runtime.flushPendingCommit();
      }
      ui._ui_commit_frame();
      needsCommit = true;
      frameRequester?.();
    },
    requestFrame: () => {
      frameRequester?.();
    },
    setFrameRequester: (requester: (() => void) | null) => {
      frameRequester = requester;
    },
    getSemanticTree: () => semanticTree,
    getActiveTextHandle: () => interactionState.getActiveTextHandle(),
    getCapturedPointerHandle: () => interactionState.getCapturedPointerHandle(),
    setCapturedPointerHandle: (handle: bigint | null) => {
      interactionState.setCapturedPointerHandle(handle);
    },
    setAppFrameHandler: (handler: ((timestampMs: number) => void) | null) => {
      appFrameHandler = handler;
      frameRequester?.();
    },
    runAppFrameHandler: (timestampMs: number) => {
      appFrameHandler?.(timestampMs);
    },
    uiNeedsAnimationFrame: () => ui._ui_needs_animation_frame() !== 0,
    getHandleFromPoint: (x: number, y: number) => handleToBigInt(core._ed_hit_test(x, y)),
    clearPointerHover: () => {
      interactionState.setLastInteractivePointerHandle(null);
    },
    refreshPointerHover: () => {
      syncAppPointerHover();
    },
    ensureFont: async (fontId: number) => {
      await ensureFontWithFallbacks(fontId);
    },
    ensureBuiltInFont: async (fontId: number) => {
      const builtInFont = getBuiltInBridgeFont(fontId);
      if (builtInFont === undefined) {
        throw new Error(`Unknown built-in font id ${String(fontId)}.`);
      }
      await ensureRegisteredFont(
        builtInFont.id,
        getBridgeAssetUrl(builtInFont.assetFile),
        builtInFont.fallbackIds,
      );
    },
    registerLazyFont: (fontId: number, url: string) => {
      lazyFontSources.set(fontId, url);
      if (loadedFonts.get(fontId) !== url) {
        loadedFonts.delete(fontId);
      }
    },
    registerFontFallback: (fontId: number, fallbackFontId: number) => {
      registerSingleFontFallback(fontId, fallbackFontId);
    },
    loadFont: async (fontId: number, url: string) => {
      loadedFonts.set(fontId, url);
      const bytes = await fetchFontBytes(url);
      registerFontBytes(fontId, bytes);
      runtime.commitFrame();
    },
    registerFont: async (font: BridgeFontRegistration) => {
      if (loadedFonts.get(font.id) !== font.url) {
        await runtime.loadFont(font.id, font.url);
      }
      if (font.fallbackIds !== undefined) {
        applyFontFallbacks(font.id, font.fallbackIds);
      }
      runtime.commitFrame();
    },
    registerFontStack: async (stack: BridgeFontStackRegistration) => {
      const fallbackFonts = stack.fallbacks ?? [];
      await Promise.all([
        runtime.loadFont(stack.primary.id, stack.primary.url),
        ...fallbackFonts.map((fallback) => runtime.loadFont(fallback.id, fallback.url)),
      ]);
      applyFontFallbacks(
        stack.primary.id,
        fallbackFonts.map((fallback) => fallback.id),
      );
      runtime.commitFrame();
    },
    loadSvg: async (svgId: number, url: string) => {
      loadedSvgs.set(svgId, url);
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Failed to fetch SVG ${url}: ${String(response.status)}`);
      }
      const bytes = new Uint8Array(await response.arrayBuffer());
      const size = parseSvgIntrinsicSize(bytes);
      const svgBytes = writeBytesToHeap(core, bytes);
      try {
        core._ed_register_svg(svgId, svgBytes.ptr, svgBytes.len);
      } finally {
        svgBytes.dispose();
      }
      runtime.commitFrame();
      return size;
    },
    loadTexture: async (textureId: number, url: string) => {
      loadedTextures.set(textureId, url);
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Failed to fetch texture ${url}: ${String(response.status)}`);
      }
      const blob = await response.blob();
      const bitmap = await decodeBlobToBitmap(blob);
      const width = bitmap.width;
      const height = bitmap.height;
      try {
        const rgba = extractBitmapRgba(bitmap);
        const textureBytes = writeBytesToHeap(core, rgba);
        try {
          core._ed_register_texture_rgba(textureId, textureBytes.ptr, width, height, textureBytes.len);
        } finally {
          textureBytes.dispose();
        }
      } finally {
        bitmap.close?.();
      }
      runtime.commitFrame();
      return {
        width,
        height,
      };
    },
    replayLoadedAssets: async () => {
      const fontReloads = Array.from(loadedFonts.entries(), async ([fontId, url]) => {
        const bytes = await fetchFontBytes(url, true);
        registerFontBytes(fontId, bytes);
      });
      await Promise.all([
        ...fontReloads,
        ...Array.from(loadedSvgs.entries(), async ([svgId, url]) => {
          const response = await fetch(url);
          if (!response.ok) {
            throw new Error(`Failed to refetch SVG ${url}: ${String(response.status)}`);
          }
          const bytes = new Uint8Array(await response.arrayBuffer());
          const svgBytes = writeBytesToHeap(core, bytes);
          try {
            core._ed_register_svg(svgId, svgBytes.ptr, svgBytes.len);
          } finally {
            svgBytes.dispose();
          }
        }),
        ...Array.from(loadedTextures.entries(), async ([textureId, url]) => {
          const response = await fetch(url);
          if (!response.ok) {
            throw new Error(`Failed to refetch texture ${url}: ${String(response.status)}`);
          }
          const blob = await response.blob();
          const bitmap = await decodeBlobToBitmap(blob);
          try {
            const rgba = extractBitmapRgba(bitmap);
            const textureBytes = writeBytesToHeap(core, rgba);
            try {
              core._ed_register_texture_rgba(textureId, textureBytes.ptr, bitmap.width, bitmap.height, textureBytes.len);
            } finally {
              textureBytes.dispose();
            }
          } finally {
            bitmap.close?.();
          }
        }),
      ]);
      for (const [fontId, fallbackIds] of fontFallbacks.entries()) {
        for (const fallbackId of fallbackIds) {
          ui._ui_register_font_fallback(fontId, fallbackId);
        }
      }
    },
    resetLogs: () => {
      resetBridgeLogs(interactionState.logs);
    },
    resetAppSession: () => {
      interactionState.resetAppSession();
    },
  };

  const refreshCanvas = (): void => {
    runtime.updateCanvasSize();
    runtime.commitFrame();
  };

  const canvasSizeSource = getCanvasSizeSource(canvas);
  const resizeObserver = typeof ResizeObserver !== 'undefined'
    ? new ResizeObserver(() => {
      refreshCanvas();
    })
    : null;
  if (resizeObserver !== null) {
    resizeObserver.observe(canvasSizeSource);
  }

  return {
    runtime,
    destroy: () => {
      resizeObserver?.disconnect();
      runtime.setFrameRequester(null);
      runtime.clearPointerHover();
      semanticTree = [];
      window.__bridgeSemanticTree = [];
      delete window.__OPEN_CANVAS_API__;
      canvas.style.cursor = 'default';
      projector.destroy();
    },
  };
}
