import type {
  BridgeLogs,
  BridgeRuntime,
  EffinDomCallbacks,
  FocusEventLog,
  PointerEventLog,
  ScrollEventLog,
  SelectionChangeLog,
  TextChangeLog,
} from '../core-types';
import type { BridgeInteractionState } from './local-types';
import { handleToBigInt, handleToString } from './utils/encoding';
import { writeUtf8ToHeap } from './utils/heap';

function currentInteractionTimeMs(): bigint {
  return BigInt(Math.floor(performance.now()));
}

function createBridgeLogs() {
  return {
    pointerEvents: [] as PointerEventLog[],
    focusEvents: [] as FocusEventLog[],
    textChanges: [] as TextChangeLog[],
    selectionChanges: [] as SelectionChangeLog[],
    crossSelectionChanges: [] as { areaHandle: string; text: string }[],
    clipboardWrites: [] as string[],
    clipboardReadRequests: [] as string[],
    scrollEvents: [] as ScrollEventLog[],
  } satisfies BridgeLogs;
}

type HiddenTextEditor = HTMLInputElement | HTMLTextAreaElement;

interface ReplacementEdit {
  readonly start: number;
  readonly end: number;
  readonly insertedText: string;
}

interface HiddenEditorWindow {
  readonly text: string;
  readonly docStart: number;
  readonly docEnd: number;
  readonly textStart: number;
  readonly textEnd: number;
}

interface PendingLocalReplacementEcho {
  readonly handle: string;
  readonly start: number;
  readonly end: number;
  readonly text: string;
}

interface PendingLocalSelectionEcho {
  readonly handle: string;
  readonly start: number;
  readonly end: number;
}

interface PendingTextMutationBatch {
  readonly handle: string;
  readonly docStart: number;
  readonly baseWindowText: string;
  readonly currentWindowText: string;
  readonly caret: number;
  readonly interactionTime: bigint;
}

const HIDDEN_EDITOR_WINDOW_OVERSCAN = 2048;
const HIDDEN_EDITOR_WINDOW_MIN_LENGTH = 4096;
const HIDDEN_EDITOR_WINDOW_REUSE_MARGIN = 512;
const TEXT_CHANGE_LOG_PREVIEW_LIMIT = 256;
const TEXTBOX_HARD_CLAMP_MAX_CODEPOINTS = 10000;

function utf8ByteLengthForCodePoint(codePoint: number): number {
  if (codePoint <= 0x7f) {
    return 1;
  }
  if (codePoint <= 0x7ff) {
    return 2;
  }
  if (codePoint <= 0xffff) {
    return 3;
  }
  return 4;
}

function advanceCodeUnitIndex(text: string, index: number): number {
  const codePoint = text.codePointAt(index) ?? 0;
  return index + (codePoint > 0xffff ? 2 : 1);
}

function retreatCodeUnitIndex(text: string, index: number): number {
  const clampedIndex = Math.max(0, Math.min(index, text.length));
  if (clampedIndex <= 0) {
    return 0;
  }
  const previousIndex = clampedIndex - 1;
  const previousUnit = text.charCodeAt(previousIndex);
  if (
    previousIndex > 0 &&
    previousUnit >= 0xdc00 &&
    previousUnit <= 0xdfff
  ) {
    const leadUnit = text.charCodeAt(previousIndex - 1);
    if (leadUnit >= 0xd800 && leadUnit <= 0xdbff) {
      return previousIndex - 1;
    }
  }
  return previousIndex;
}

function codeUnitIndexToUtf8ByteOffset(text: string, index: number): number {
  const clampedIndex = Math.max(0, Math.min(index, text.length));
  let byteOffset = 0;
  for (let current = 0; current < clampedIndex; current = advanceCodeUnitIndex(text, current)) {
    const codePoint = text.codePointAt(current) ?? 0;
    byteOffset += utf8ByteLengthForCodePoint(codePoint);
  }
  return byteOffset;
}

function utf8ByteLength(text: string): number {
  return codeUnitIndexToUtf8ByteOffset(text, text.length);
}

interface TextClampRange {
  readonly start: number;
  readonly end: number;
}

function isLineBreakCodeUnit(text: string, index: number): boolean {
  if (index < 0 || index >= text.length) {
    return false;
  }
  const codeUnit = text.charCodeAt(index);
  return codeUnit === 0x0a || codeUnit === 0x0d;
}

function collectTextboxHardLineClampRanges(text: string): readonly TextClampRange[] {
  const ranges: TextClampRange[] = [];
  let index = 0;
  while (index < text.length) {
    let lineCapEnd = index;
    let lineEnd = index;
    let codePointCount = 0;
    while (lineEnd < text.length && !isLineBreakCodeUnit(text, lineEnd)) {
      const next = advanceCodeUnitIndex(text, lineEnd);
      if (codePointCount < TEXTBOX_HARD_CLAMP_MAX_CODEPOINTS) {
        lineCapEnd = next;
      }
      codePointCount += 1;
      lineEnd = next;
    }
    if (codePointCount > TEXTBOX_HARD_CLAMP_MAX_CODEPOINTS) {
      ranges.push({ start: lineCapEnd, end: lineEnd });
    }
    if (lineEnd >= text.length) {
      break;
    }
    if (text.charCodeAt(lineEnd) === 0x0d && lineEnd + 1 < text.length && text.charCodeAt(lineEnd + 1) === 0x0a) {
      index = lineEnd + 2;
    } else {
      index = lineEnd + 1;
    }
  }
  return ranges;
}

function mapClampedTextIndex(index: number, ranges: readonly TextClampRange[]): number {
  const clampedIndex = Math.max(0, index);
  let removedBefore = 0;
  for (const range of ranges) {
    if (clampedIndex <= range.start) {
      break;
    }
    if (clampedIndex < range.end) {
      return range.start - removedBefore;
    }
    removedBefore += range.end - range.start;
  }
  return clampedIndex - removedBefore;
}

function clampTextboxHardLines(text: string): {
  readonly text: string;
  readonly changed: boolean;
  mapIndex(index: number): number;
} {
  const ranges = collectTextboxHardLineClampRanges(text);
  if (ranges.length === 0) {
    return {
      text,
      changed: false,
      mapIndex: (index: number) => Math.max(0, Math.min(index, text.length)),
    };
  }
  let result = '';
  let cursor = 0;
  for (const range of ranges) {
    result += text.slice(cursor, range.start);
    cursor = range.end;
  }
  result += text.slice(cursor);
  return {
    text: result,
    changed: true,
    mapIndex: (index: number) => mapClampedTextIndex(index, ranges),
  };
}

function utf8ByteOffsetToCodeUnitIndex(text: string, byteOffset: number, textByteLength?: number): number {
  const byteLimit = textByteLength ?? utf8ByteLength(text);
  const target = Math.max(0, Math.min(byteOffset, byteLimit));
  let currentByteOffset = 0;
  let currentIndex = 0;
  while (currentIndex < text.length) {
    const codePoint = text.codePointAt(currentIndex) ?? 0;
    const nextByteOffset = currentByteOffset + utf8ByteLengthForCodePoint(codePoint);
    if (nextByteOffset > target) {
      break;
    }
    currentByteOffset = nextByteOffset;
    currentIndex = advanceCodeUnitIndex(text, currentIndex);
    if (currentByteOffset === target) {
      break;
    }
  }
  return currentIndex;
}

function computeReplacementEdit(previousText: string, nextText: string): ReplacementEdit | null {
  if (previousText === nextText) {
    return null;
  }
  const sharedPrefixLimit = Math.min(previousText.length, nextText.length);
  let prefix = 0;
  while (prefix < sharedPrefixLimit && previousText.charCodeAt(prefix) === nextText.charCodeAt(prefix)) {
    prefix += 1;
  }

  let suffix = 0;
  while (
    suffix < (previousText.length - prefix) &&
    suffix < (nextText.length - prefix) &&
    previousText.charCodeAt(previousText.length - suffix - 1) === nextText.charCodeAt(nextText.length - suffix - 1)
  ) {
    suffix += 1;
  }

  return {
    start: prefix,
    end: previousText.length - suffix,
    insertedText: nextText.slice(prefix, nextText.length - suffix),
  };
}

function applyUtf8ByteReplacementEdit(text: string, start: number, end: number, insertedText: string): string {
  const clampedStart = utf8ByteOffsetToCodeUnitIndex(text, Math.max(0, start));
  const clampedEnd = utf8ByteOffsetToCodeUnitIndex(text, Math.max(clampedStart, end));
  return `${text.slice(0, clampedStart)}${insertedText}${text.slice(clampedEnd)}`;
}

function buildClampedTextboxEdit(
  fullPreviousText: string,
  absoluteStart: number,
  absoluteEnd: number,
  insertedText: string,
  absoluteCaret: number,
): {
  readonly fullNextText: string;
  readonly replacement: ReplacementEdit | null;
  readonly caretByte: number;
  readonly clampChanged: boolean;
} {
  const replaceStart = utf8ByteOffsetToCodeUnitIndex(fullPreviousText, absoluteStart);
  const replaceEnd = utf8ByteOffsetToCodeUnitIndex(fullPreviousText, absoluteEnd);
  const intendedFullNextText =
    `${fullPreviousText.slice(0, replaceStart)}${insertedText}${fullPreviousText.slice(replaceEnd)}`;
  const intendedCaret = utf8ByteOffsetToCodeUnitIndex(intendedFullNextText, absoluteCaret);
  const clamped = clampTextboxHardLines(intendedFullNextText);
  const finalCaret = clamped.mapIndex(intendedCaret);
  return {
    fullNextText: clamped.text,
    replacement: computeReplacementEdit(fullPreviousText, clamped.text),
    caretByte: codeUnitIndexToUtf8ByteOffset(clamped.text, finalCaret),
    clampChanged: clamped.changed,
  };
}

function summarizeTextChange(handle: string, text: string): TextChangeLog {
  if (text.length <= TEXT_CHANGE_LOG_PREVIEW_LIMIT) {
    return { handle, text };
  }
  return {
    handle,
    text: `${text.slice(0, TEXT_CHANGE_LOG_PREVIEW_LIMIT)}…`,
    textLength: text.length,
    truncated: true,
  };
}

function buildHiddenEditorWindow(
  text: string,
  start: number,
  end: number,
  textByteLength: number,
  previousWindow?: HiddenEditorWindow,
): HiddenEditorWindow {
  const normalizedStart = Math.max(0, Math.min(start, text.length));
  const normalizedEnd = Math.max(normalizedStart, Math.min(end, text.length));
  const selectionSpan = normalizedEnd - normalizedStart;
  const targetLength = Math.max(
    HIDDEN_EDITOR_WINDOW_MIN_LENGTH,
    selectionSpan + (HIDDEN_EDITOR_WINDOW_OVERSCAN * 2),
  );
  if (text.length <= targetLength) {
    return {
      text,
      docStart: 0,
      docEnd: textByteLength,
      textStart: 0,
      textEnd: text.length,
    };
  }

  if (previousWindow !== undefined) {
    const previousLength = previousWindow.textEnd - previousWindow.textStart;
    const clampedPreviousStart = Math.max(0, Math.min(previousWindow.textStart, text.length));
    const clampedPreviousEnd = Math.max(clampedPreviousStart, Math.min(previousWindow.textEnd, text.length));
    if (previousLength > 0 &&
        clampedPreviousEnd > clampedPreviousStart &&
        clampedPreviousEnd - clampedPreviousStart >= targetLength) {
      const reuseMargin = Math.min(
        HIDDEN_EDITOR_WINDOW_REUSE_MARGIN,
        Math.max(0, Math.floor((clampedPreviousEnd - clampedPreviousStart) / 4)),
      );
      const reusableStart = clampedPreviousStart + reuseMargin;
      const reusableEnd = clampedPreviousEnd - reuseMargin;
      if (normalizedStart >= reusableStart && normalizedEnd <= reusableEnd) {
        return {
          text: text.slice(clampedPreviousStart, clampedPreviousEnd),
          docStart: previousWindow.docStart,
          docEnd: previousWindow.docEnd,
          textStart: clampedPreviousStart,
          textEnd: clampedPreviousEnd,
        };
      }
    }
  }

  let docStart = Math.max(0, normalizedStart - HIDDEN_EDITOR_WINDOW_OVERSCAN);
  let docEnd = Math.min(text.length, normalizedEnd + HIDDEN_EDITOR_WINDOW_OVERSCAN);
  const currentLength = docEnd - docStart;
  if (currentLength < targetLength) {
    let remaining = targetLength - currentLength;
    const extendBefore = Math.min(docStart, Math.floor(remaining / 2));
    docStart -= extendBefore;
    remaining -= extendBefore;
    const extendAfter = Math.min(text.length - docEnd, remaining);
    docEnd += extendAfter;
    remaining -= extendAfter;
    if (remaining > 0) {
      const extraBefore = Math.min(docStart, remaining);
      docStart -= extraBefore;
      remaining -= extraBefore;
      if (remaining > 0) {
        docEnd = Math.min(text.length, docEnd + remaining);
      }
    }
  }

  return {
    text: text.slice(docStart, docEnd),
    docStart: codeUnitIndexToUtf8ByteOffset(text, docStart),
    docEnd: codeUnitIndexToUtf8ByteOffset(text, docEnd),
    textStart: docStart,
    textEnd: docEnd,
  };
}

function createHiddenTextEditor(multiline: boolean): HiddenTextEditor {
  const editor = multiline ? document.createElement('textarea') : document.createElement('input');
  if (editor instanceof HTMLInputElement) {
    editor.type = 'text';
  } else {
    editor.rows = 1;
    editor.wrap = 'off';
    editor.style.resize = 'none';
    editor.style.whiteSpace = 'pre';
  }
  editor.autocapitalize = 'off';
  editor.autocomplete = 'off';
  editor.autocorrect = false;
  editor.spellcheck = false;
  editor.tabIndex = -1;
  editor.dataset.effindomHiddenEditor = 'true';
  editor.setAttribute('aria-label', multiline ? 'EffinDom multiline text input' : 'EffinDom text input');
  if (editor instanceof HTMLTextAreaElement) {
    editor.setAttribute('aria-multiline', 'true');
  }
  editor.style.position = 'fixed';
  editor.style.left = '-9999px';
  editor.style.top = '0';
  editor.style.width = '1px';
  editor.style.height = '1px';
  editor.style.opacity = '0';
  editor.style.pointerEvents = 'none';
  editor.style.font = '16px "Noto Sans Symbols 2", "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", monospace';
  editor.style.overflow = 'hidden';
  document.body.appendChild(editor);
  return editor;
}

export function installCallbacks(runtimeRef: { current: BridgeRuntime | null }): BridgeInteractionState {
  const logs = createBridgeLogs();
  const textByHandle = Object.create(null) as Record<string, string>;
  const selectionsByHandle = Object.create(null) as Record<string, { start: number; end: number }>;
  const hiddenInput = createHiddenTextEditor(false) as HTMLInputElement;
  const hiddenTextarea = createHiddenTextEditor(true) as HTMLTextAreaElement;
  let activeTextHandle: bigint | null = null;
  let hiddenInputIsComposing = false;
  let lastPointerClientX: number | null = null;
  let lastPointerClientY: number | null = null;
  let lastPointerX = 0;
  let lastPointerY = 0;
  let lastPointerModifiers = 0;
  let lastInteractivePointerHandle: bigint | null = null;
  let capturedPointerHandle: bigint | null = null;
  let pointerInsideCanvas = false;
  let appSessionVersion = 0;
  let activeTextEditable = false;
  let activeTextMultiline = false;
  let activeEditorWindow: HiddenEditorWindow = { text: '', docStart: 0, docEnd: 0, textStart: 0, textEnd: 0 };
  const textByteLengthsByHandle = Object.create(null) as Record<string, number>;
  const pendingCaretRevealByHandle = Object.create(null) as Record<string, boolean>;
  let pendingCaretRevealFrame: number | null = null;
  let pendingLocalReplacementEcho: PendingLocalReplacementEcho | null = null;
  let pendingLocalSelectionEcho: PendingLocalSelectionEcho | null = null;
  let pendingTextMutationBatch: PendingTextMutationBatch | null = null;
  let deferredTouchFocusHandle: string | null = null;
  window.__bridgeLogs = logs;
  window.__bridgeTextByHandle = textByHandle;
  window.__bridgeSelectionsByHandle = selectionsByHandle;
  window.__bridgeActiveEditorWindow = { handle: null, ...activeEditorWindow };

  const getActiveEditor = (): HiddenTextEditor => (activeTextMultiline ? hiddenTextarea : hiddenInput);

  const isActiveEditorFocused = (): boolean => document.activeElement === getActiveEditor();

  const clampSelectionToText = (length: number, selection: { start: number; end: number }): { start: number; end: number } => ({
    start: Math.max(0, Math.min(selection.start, length)),
    end: Math.max(0, Math.min(selection.end, length)),
  });

  const syncActiveEditorWindowDebug = (handle: string | null): void => {
    window.__bridgeActiveEditorWindow = {
      handle,
      text: activeEditorWindow.text,
      docStart: activeEditorWindow.docStart,
      docEnd: activeEditorWindow.docEnd,
    };
  };

  const clearActiveEditorWindow = (): void => {
    activeEditorWindow = { text: '', docStart: 0, docEnd: 0, textStart: 0, textEnd: 0 };
    syncActiveEditorWindowDebug(null);
  };
  const clearPendingCaretReveal = (): void => {
    if (pendingCaretRevealFrame !== null) {
      cancelAnimationFrame(pendingCaretRevealFrame);
      pendingCaretRevealFrame = null;
    }
    for (const key of Object.keys(pendingCaretRevealByHandle)) {
      delete pendingCaretRevealByHandle[key];
    }
  };

  const clearPendingTextMutations = (): void => {
    pendingTextMutationBatch = null;
  };

  const updateActiveEditorWindowText = (text: string): void => {
    activeEditorWindow = {
      text,
      docStart: activeEditorWindow.docStart,
      docEnd: activeEditorWindow.docStart + utf8ByteLength(text),
      textStart: activeEditorWindow.textStart,
      textEnd: activeEditorWindow.textStart + text.length,
    };
    syncActiveEditorWindowDebug(activeTextHandle?.toString() ?? null);
  };

  const materializePendingTextMutations = (): boolean => {
    const runtime = runtimeRef.current;
    const batch = pendingTextMutationBatch;
    if (runtime === null || batch === null) {
      return false;
    }
    pendingTextMutationBatch = null;
    const handle = handleToBigInt(batch.handle);
    const absoluteCaret = batch.docStart + codeUnitIndexToUtf8ByteOffset(batch.currentWindowText, batch.caret);
    runtime.ui._ui_set_interaction_time(batch.interactionTime);
    const replacement = computeReplacementEdit(batch.baseWindowText, batch.currentWindowText);
    if (replacement === null) {
      pendingLocalSelectionEcho = {
        handle: batch.handle,
        start: absoluteCaret,
        end: absoluteCaret,
      };
      runtime.ui._ui_set_text_selection_range(handle, absoluteCaret, absoluteCaret);
      return true;
    }

    const absoluteStart = batch.docStart + codeUnitIndexToUtf8ByteOffset(batch.baseWindowText, replacement.start);
    const absoluteEnd = batch.docStart + codeUnitIndexToUtf8ByteOffset(batch.baseWindowText, replacement.end);
    pendingLocalReplacementEcho = {
      handle: batch.handle,
      start: absoluteStart,
      end: absoluteEnd,
      text: replacement.insertedText,
    };
    pendingLocalSelectionEcho = {
      handle: batch.handle,
      start: absoluteCaret,
      end: absoluteCaret,
    };
    const heapString = writeUtf8ToHeap(runtime.ui, replacement.insertedText);
    try {
      runtime.ui._ui_replace_text_range(
        handle,
        absoluteStart,
        absoluteEnd,
        heapString.ptr,
        heapString.len,
        absoluteCaret,
      );
    } finally {
      heapString.dispose();
    }
    return true;
  };

  const detachBridgeTextInput = (): void => {
    hiddenInput.blur();
    hiddenTextarea.blur();
  };

  const getTextboxState = (handleKey: string): { isTextbox: boolean; isEditable: boolean; isMultiline: boolean } => {
    const runtime = runtimeRef.current;
    if (runtime === null) {
      return { isTextbox: false, isEditable: false, isMultiline: false };
    }
    const node = runtime.getSemanticTree().find((entry) => entry.handle === handleKey);
    if (node?.roleName !== 'textbox') {
      return { isTextbox: false, isEditable: false, isMultiline: false };
    }
    return {
      isTextbox: true,
      isEditable: node.state.readonly !== true,
      isMultiline: node.state.multiline === true,
    };
  };

  const syncFocusedInputState = (): void => {
    if (activeTextHandle === null) {
      clearActiveEditorWindow();
      detachBridgeTextInput();
      return;
    }

    const activeEditor = getActiveEditor();
    const handleKey = activeTextHandle.toString();
    const text = textByHandle[handleKey] ?? '';
    const textByteLength = textByteLengthsByHandle[handleKey] ?? utf8ByteLength(text);
    textByteLengthsByHandle[handleKey] = textByteLength;
    const selection = selectionsByHandle[handleKey] ?? { start: textByteLength, end: textByteLength };
    const { start: startByte, end: endByte } = clampSelectionToText(textByteLength, selection);
    const start = utf8ByteOffsetToCodeUnitIndex(text, startByte, textByteLength);
    const end = utf8ByteOffsetToCodeUnitIndex(text, endByte, textByteLength);
    const direction = start === end ? 'none' : (startByte < endByte ? 'forward' : 'backward');
    const normalizedStart = Math.min(start, end);
    const normalizedEnd = Math.max(start, end);
    activeEditorWindow = buildHiddenEditorWindow(text, normalizedStart, normalizedEnd, textByteLength, activeEditorWindow);
    syncActiveEditorWindowDebug(handleKey);
    const localStart = normalizedStart - activeEditorWindow.textStart;
    const localEnd = normalizedEnd - activeEditorWindow.textStart;
    if (activeEditor.value !== activeEditorWindow.text) {
      activeEditor.value = activeEditorWindow.text;
    }
    activeEditor.readOnly = !activeTextEditable;
    activeEditor.setSelectionRange(localStart, localEnd, direction);
  };

  const focusHiddenEditorNow = (): void => {
    getActiveEditor().focus({ preventScroll: true });
    syncFocusedInputState();
  };

  const refocusActiveTextInput = (): void => {
    if (activeTextHandle === null) {
      if (deferredTouchFocusHandle === null) {
        return;
      }
      const textboxState = getTextboxState(deferredTouchFocusHandle);
      if (!textboxState.isTextbox) {
        return;
      }
      activeTextHandle = handleToBigInt(deferredTouchFocusHandle);
      activeTextEditable = textboxState.isEditable;
      activeTextMultiline = textboxState.isMultiline;
      syncFocusedInputState();
      focusHiddenEditorNow();
      return;
    }
    focusHiddenEditorNow();
  };

  const beginTouchTextFocusDeferral = (handle: bigint): void => {
    deferredTouchFocusHandle = handle.toString();
  };

  const cancelTouchTextFocusDeferral = (): void => {
    deferredTouchFocusHandle = null;
  };

  const commitTouchTextFocusDeferral = (handle: bigint): void => {
    const handleKey = handle.toString();
    if (deferredTouchFocusHandle !== handleKey) {
      return;
    }
    deferredTouchFocusHandle = null;
    if (activeTextHandle?.toString() !== handleKey) {
      return;
    }
    if (!isActiveEditorFocused()) {
      focusHiddenEditorNow();
    }
  };

  const scheduleCaretRevealReplay = (handleKey: string): void => {
    if (!pendingCaretRevealByHandle[handleKey] || activeTextHandle?.toString() !== handleKey) {
      return;
    }
    if (pendingCaretRevealFrame !== null) {
      return;
    }
    pendingCaretRevealFrame = requestAnimationFrame(() => {
      pendingCaretRevealFrame = null;
      if (!pendingCaretRevealByHandle[handleKey] || activeTextHandle?.toString() !== handleKey) {
        return;
      }
      delete pendingCaretRevealByHandle[handleKey];
      const runtime = runtimeRef.current;
      if (runtime === null) {
        return;
      }
      const text = textByHandle[handleKey] ?? '';
      const textByteLength = utf8ByteLength(text);
      const selection = selectionsByHandle[handleKey] ?? { start: textByteLength, end: textByteLength };
      const { start, end } = clampSelectionToText(textByteLength, selection);
      runtime.ui._ui_set_text_selection_range(handleToBigInt(handleKey), start, end);
    });
  };

  const clearRecordMap = <T>(record: Record<string, T>): void => {
    for (const key of Object.keys(record)) {
      delete record[key];
    }
  };

  const resetAppSession = (): void => {
    appSessionVersion += 1;
    clearRecordMap(textByHandle);
    clearRecordMap(textByteLengthsByHandle);
    clearRecordMap(selectionsByHandle);
    clearPendingCaretReveal();
    clearPendingTextMutations();
    pendingLocalReplacementEcho = null;
    pendingLocalSelectionEcho = null;
    deferredTouchFocusHandle = null;
    activeTextHandle = null;
    activeTextEditable = false;
    activeTextMultiline = false;
    clearActiveEditorWindow();
    hiddenInputIsComposing = false;
    lastInteractivePointerHandle = null;
    capturedPointerHandle = null;
    hiddenInput.value = '';
    hiddenInput.setSelectionRange(0, 0, 'none');
    hiddenTextarea.value = '';
    hiddenTextarea.setSelectionRange(0, 0, 'none');
    detachBridgeTextInput();
  };

  const commitReplacementEdit = (
    previousText: string,
    nextText: string,
    replacement: ReplacementEdit,
    caret: number,
  ): void => {
    const runtime = runtimeRef.current;
    if (runtime === null || activeTextHandle === null) {
      return;
    }
    const clampedStart = Math.max(0, Math.min(replacement.start, previousText.length));
    const clampedEnd = Math.max(clampedStart, Math.min(replacement.end, previousText.length));
    const activeHandleKey = activeTextHandle.toString();
    if (pendingTextMutationBatch === null && runtime.hasPendingCommit()) {
      runtime.flushPendingCommit();
    }

    const absoluteStart = activeEditorWindow.docStart + codeUnitIndexToUtf8ByteOffset(previousText, clampedStart);
    const absoluteEnd = activeEditorWindow.docStart + codeUnitIndexToUtf8ByteOffset(previousText, clampedEnd);
    const intendedAbsoluteCaret = activeEditorWindow.docStart + codeUnitIndexToUtf8ByteOffset(nextText, Math.max(0, Math.min(caret, nextText.length)));
    const fullPreviousText = textByHandle[activeHandleKey] ?? '';
    const clampedEdit = buildClampedTextboxEdit(
      fullPreviousText,
      absoluteStart,
      absoluteEnd,
      replacement.insertedText,
      intendedAbsoluteCaret,
    );
    if (clampedEdit.clampChanged) {
      if (pendingTextMutationBatch !== null) {
        materializePendingTextMutations();
        runtime.commitFrame();
      }
      if (runtime.hasPendingCommit()) {
        runtime.flushPendingCommit();
      }
      clearPendingTextMutations();
      textByHandle[activeHandleKey] = clampedEdit.fullNextText;
      textByteLengthsByHandle[activeHandleKey] = utf8ByteLength(clampedEdit.fullNextText);
      selectionsByHandle[activeHandleKey] = { start: clampedEdit.caretByte, end: clampedEdit.caretByte };
      syncFocusedInputState();
    } else {
      textByHandle[activeHandleKey] = clampedEdit.fullNextText;
      textByteLengthsByHandle[activeHandleKey] = utf8ByteLength(clampedEdit.fullNextText);
      selectionsByHandle[activeHandleKey] = { start: clampedEdit.caretByte, end: clampedEdit.caretByte };
      updateActiveEditorWindowText(nextText);
    }

    if (clampedEdit.replacement === null) {
      return;
    }

    if (clampedEdit.clampChanged) {
      const replacementStartByte = codeUnitIndexToUtf8ByteOffset(fullPreviousText, clampedEdit.replacement.start);
      const replacementEndByte = codeUnitIndexToUtf8ByteOffset(fullPreviousText, clampedEdit.replacement.end);
      pendingLocalReplacementEcho = {
        handle: activeHandleKey,
        start: replacementStartByte,
        end: replacementEndByte,
        text: clampedEdit.replacement.insertedText,
      };
      pendingLocalSelectionEcho = {
        handle: activeHandleKey,
        start: clampedEdit.caretByte,
        end: clampedEdit.caretByte,
      };
      runtime.ui._ui_set_interaction_time(currentInteractionTimeMs());
      const heapString = writeUtf8ToHeap(runtime.ui, clampedEdit.replacement.insertedText);
      try {
        runtime.ui._ui_replace_text_range(
          activeTextHandle,
          replacementStartByte,
          replacementEndByte,
          heapString.ptr,
          heapString.len,
          clampedEdit.caretByte,
        );
      } finally {
        heapString.dispose();
      }
      runtime.commitFrame();
      return;
    }

    if (
      pendingTextMutationBatch !== null &&
      (pendingTextMutationBatch.handle !== activeHandleKey || pendingTextMutationBatch.docStart !== activeEditorWindow.docStart)
    ) {
      materializePendingTextMutations();
      runtime.commitFrame();
      runtime.flushPendingCommit();
    }

    pendingTextMutationBatch = pendingTextMutationBatch === null
      ? {
          handle: activeHandleKey,
          docStart: activeEditorWindow.docStart,
          baseWindowText: previousText,
          currentWindowText: getActiveEditor().value,
          caret: getActiveEditor().selectionStart ?? getActiveEditor().value.length,
          interactionTime: currentInteractionTimeMs(),
        }
      : {
          ...pendingTextMutationBatch,
          currentWindowText: getActiveEditor().value,
          caret: getActiveEditor().selectionStart ?? getActiveEditor().value.length,
          interactionTime: currentInteractionTimeMs(),
        };
    runtime.requestFrame();
  };

  const commitImeEdit = (text: string, caret: number): void => {
    const previousText = activeEditorWindow.text;
    const replacement = computeReplacementEdit(previousText, text);
    if (replacement === null) {
      const runtime = runtimeRef.current;
      if (runtime !== null) {
        runtime.commitFrame();
      }
      return;
    }
    commitReplacementEdit(previousText, text, replacement, caret);
  };

  const applyActiveTextDeletion = (forward: boolean): boolean => {
    if (activeTextHandle === null || !activeTextEditable || hiddenInputIsComposing || !isActiveEditorFocused()) {
      return false;
    }
    const editor = getActiveEditor();
    const text = editor.value;
    const selectionStart = editor.selectionStart ?? text.length;
    const selectionEnd = editor.selectionEnd ?? selectionStart;
    const rangeStart = Math.min(selectionStart, selectionEnd);
    const rangeEnd = Math.max(selectionStart, selectionEnd);
    let nextText = text;
    let nextCaret = rangeStart;
    let replacementStart = rangeStart;
    let replacementEnd = rangeEnd;
    if (rangeStart != rangeEnd) {
      nextText = text.slice(0, rangeStart) + text.slice(rangeEnd);
    } else if (forward) {
      if (rangeStart >= text.length) {
        return true;
      }
      replacementEnd = advanceCodeUnitIndex(text, rangeStart);
      nextText = text.slice(0, rangeStart) + text.slice(replacementEnd);
    } else {
      if (rangeStart == 0) {
        return true;
      }
      replacementStart = retreatCodeUnitIndex(text, rangeStart);
      nextCaret = replacementStart;
      nextText = text.slice(0, nextCaret) + text.slice(rangeStart);
    }
    editor.value = nextText;
    editor.setSelectionRange(nextCaret, nextCaret, 'none');
    commitReplacementEdit(
      text,
      nextText,
      {
        start: replacementStart,
        end: replacementEnd,
        insertedText: '',
      },
      nextCaret,
    );
    return true;
  };

  const attachHiddenEditorListeners = (editor: HiddenTextEditor): void => {
    editor.addEventListener('compositionstart', () => {
      hiddenInputIsComposing = true;
    });

    editor.addEventListener('input', () => {
      if (hiddenInputIsComposing) {
        return;
      }
      commitImeEdit(editor.value, editor.selectionStart ?? editor.value.length);
    });

    editor.addEventListener('compositionend', () => {
      hiddenInputIsComposing = false;
      commitImeEdit(editor.value, editor.selectionStart ?? editor.value.length);
    });
  };

  attachHiddenEditorListeners(hiddenInput);
  attachHiddenEditorListeners(hiddenTextarea);

  const callbacks: EffinDomCallbacks = {
    onPointerEvent: (handle, eventType) => {
      const entry: PointerEventLog = { handle: handleToString(handle), eventType };
      logs.pointerEvents.push(entry);
      window.__effindomCallbacks?.onPointerEventWithCoords?.(
        eventType,
        handle,
        lastPointerX,
        lastPointerY,
        lastPointerModifiers,
      );
    },
    onFocusChanged: (handle, isFocused) => {
      const handleKey = handleToString(handle);
      const entry: FocusEventLog = { handle: handleKey, isFocused };
      logs.focusEvents.push(entry);
      if (isFocused) {
        const textboxState = getTextboxState(handleKey);
        if (!textboxState.isTextbox) {
          deferredTouchFocusHandle = null;
          delete pendingCaretRevealByHandle[handleKey];
          activeTextHandle = null;
          activeTextEditable = false;
          activeTextMultiline = false;
          syncFocusedInputState();
          return;
        }
        activeTextHandle = handleToBigInt(handle);
        activeTextEditable = textboxState.isEditable;
        activeTextMultiline = textboxState.isMultiline;
        syncFocusedInputState();
        if (deferredTouchFocusHandle === handleKey) {
          return;
        }
        window.setTimeout(() => {
          if (activeTextHandle !== null && activeTextHandle.toString() === handleKey) {
            focusHiddenEditorNow();
          }
        }, 0);
      } else if (activeTextHandle !== null && activeTextHandle.toString() === handleKey) {
        if (deferredTouchFocusHandle === handleKey) {
          return;
        }
        deferredTouchFocusHandle = null;
        runtimeRef.current?.flushPendingCommit();
        delete pendingCaretRevealByHandle[handleKey];
        pendingLocalReplacementEcho = null;
        pendingLocalSelectionEcho = null;
        clearPendingTextMutations();
        activeTextHandle = null;
        activeTextEditable = false;
        activeTextMultiline = false;
        syncFocusedInputState();
      }
    },
    onTextChanged: (handle, text) => {
      const handleKey = handleToString(handle);
      if (pendingLocalReplacementEcho !== null && pendingLocalReplacementEcho.handle === handleKey) {
        pendingLocalReplacementEcho = null;
      }
      textByHandle[handleKey] = text;
      textByteLengthsByHandle[handleKey] = utf8ByteLength(text);
      const entry = summarizeTextChange(handleKey, text);
      logs.textChanges.push(entry);
      if (activeTextHandle !== null && activeTextHandle.toString() === handleKey) {
        pendingCaretRevealByHandle[handleKey] = true;
        if (!isActiveEditorFocused()) {
          focusHiddenEditorNow();
          return;
        }
        syncFocusedInputState();
      }
    },
    onTextReplaced: (handle, start, end, text) => {
      const handleKey = handleToString(handle);
      const previousText = textByHandle[handleKey] ?? '';
      const previousTextByteLength = textByteLengthsByHandle[handleKey] ?? utf8ByteLength(previousText);
      const isLocalEcho = pendingLocalReplacementEcho !== null
        && pendingLocalReplacementEcho.handle === handleKey
        && pendingLocalReplacementEcho.start === start
        && pendingLocalReplacementEcho.end === end
        && pendingLocalReplacementEcho.text === text
        && activeTextHandle !== null
        && activeTextHandle.toString() === handleKey
        && isActiveEditorFocused();
      const nextText = isLocalEcho
        ? previousText
        : applyUtf8ByteReplacementEdit(previousText, start, end, text);
      if (!isLocalEcho) {
        textByHandle[handleKey] = nextText;
        textByteLengthsByHandle[handleKey] = previousTextByteLength - (end - start) + utf8ByteLength(text);
      }
      if (isLocalEcho) {
        pendingLocalReplacementEcho = null;
      }
      const entry = summarizeTextChange(handleKey, nextText);
      logs.textChanges.push(entry);
      if (activeTextHandle !== null && activeTextHandle.toString() === handleKey) {
        pendingCaretRevealByHandle[handleKey] = true;
        if (!isActiveEditorFocused()) {
          focusHiddenEditorNow();
          return;
        }
        if (!isLocalEcho) {
          syncFocusedInputState();
        }
      }
    },
    onSelectionChanged: (handle, start, end) => {
      const handleKey = handleToString(handle);
      const isLocalEcho = pendingLocalSelectionEcho !== null
        && pendingLocalSelectionEcho.handle === handleKey
        && pendingLocalSelectionEcho.start === start
        && pendingLocalSelectionEcho.end === end
        && activeTextHandle !== null
        && activeTextHandle.toString() === handleKey
        && isActiveEditorFocused();
      selectionsByHandle[handleKey] = { start, end };
      if (pendingLocalSelectionEcho !== null && pendingLocalSelectionEcho.handle === handleKey) {
        pendingLocalSelectionEcho = null;
      }
      const entry: SelectionChangeLog = { handle: handleKey, start, end };
      logs.selectionChanges.push(entry);
      if (activeTextHandle !== null && activeTextHandle.toString() === handleKey) {
        if (!isActiveEditorFocused()) {
          focusHiddenEditorNow();
          return;
        }
        if (!isLocalEcho) {
          syncFocusedInputState();
        }
        scheduleCaretRevealReplay(handleKey);
      }
    },
    onScroll: (handle, offsetX, offsetY, contentWidth, contentHeight, viewportWidth, viewportHeight) => {
      const entry: ScrollEventLog = {
        handle: handleToString(handle),
        offsetX,
        offsetY,
        contentWidth,
        contentHeight,
        viewportWidth,
        viewportHeight,
      };
      logs.scrollEvents.push(entry);
    },
    onCrossSelectionChanged: (areaHandle, text) => {
      logs.crossSelectionChanges.push({ areaHandle: handleToString(areaHandle), text });
    },
    onClipboardWrite: (text) => {
      logs.clipboardWrites.push(text);
      void navigator.clipboard.writeText(text).catch(() => undefined);
    },
    onClipboardRead: (handle) => {
      const runtime = runtimeRef.current;
      if (runtime === null) {
        return;
      }
      const handleValue = handleToBigInt(handle);
      const requestSessionVersion = appSessionVersion;
      logs.clipboardReadRequests.push(handleValue.toString());
      void navigator.clipboard.readText().then((text) => {
        if (requestSessionVersion !== appSessionVersion) {
          return;
        }
        const handleKey = handleValue.toString();
        const currentText = textByHandle[handleKey] ?? '';
        const currentTextByteLength = textByteLengthsByHandle[handleKey] ?? utf8ByteLength(currentText);
        const selection = selectionsByHandle[handleKey] ?? { start: currentTextByteLength, end: currentTextByteLength };
        const rangeStart = Math.max(0, Math.min(selection.start, selection.end));
        const rangeEnd = Math.max(rangeStart, Math.min(currentTextByteLength, Math.max(selection.start, selection.end)));
        const clampedEdit = buildClampedTextboxEdit(
          currentText,
          rangeStart,
          rangeEnd,
          text,
          rangeStart + utf8ByteLength(text),
        );
        textByHandle[handleKey] = clampedEdit.fullNextText;
        textByteLengthsByHandle[handleKey] = utf8ByteLength(clampedEdit.fullNextText);
        selectionsByHandle[handleKey] = { start: clampedEdit.caretByte, end: clampedEdit.caretByte };
        if (activeTextHandle !== null && activeTextHandle.toString() === handleKey) {
          syncFocusedInputState();
        }
        if (clampedEdit.replacement === null) {
          return;
        }
        runtime.ui._ui_set_interaction_time(currentInteractionTimeMs());
        const replacementStartByte = codeUnitIndexToUtf8ByteOffset(currentText, clampedEdit.replacement.start);
        const replacementEndByte = codeUnitIndexToUtf8ByteOffset(currentText, clampedEdit.replacement.end);
        pendingLocalReplacementEcho = {
          handle: handleKey,
          start: replacementStartByte,
          end: replacementEndByte,
          text: clampedEdit.replacement.insertedText,
        };
        pendingLocalSelectionEcho = {
          handle: handleKey,
          start: clampedEdit.caretByte,
          end: clampedEdit.caretByte,
        };
        const heapString = writeUtf8ToHeap(runtime.ui, clampedEdit.replacement.insertedText);
        try {
          runtime.ui._ui_replace_text_range(
            handleValue,
            replacementStartByte,
            replacementEndByte,
            heapString.ptr,
            heapString.len,
            clampedEdit.caretByte,
          );
        } finally {
          heapString.dispose();
        }
        runtime.commitFrame();
      }).catch(() => undefined);
    },
    onRequestFontLoad: (fontId, url) => {
      const runtime = runtimeRef.current;
      if (runtime === null || url.length === 0) {
        return;
      }
      void runtime.loadFont(fontId, url).catch((error: unknown) => {
        window.__bridgeError = error instanceof Error ? error.message : String(error);
      });
    },
  };

  window.__effindomCallbacks = callbacks;

  return {
    logs,
    textByHandle,
    selectionsByHandle,
    hasPendingTextMutations: () => pendingTextMutationBatch !== null,
    materializePendingTextMutations,
    getActiveTextEditable: () => activeTextEditable,
    getActiveTextHandle: () => activeTextHandle,
    getActiveTextMultiline: () => activeTextMultiline,
    getCapturedPointerHandle: () => capturedPointerHandle,
    getLastPointerClientPosition: () => ({ x: lastPointerClientX, y: lastPointerClientY }),
    getLastPointerPosition: () => ({ x: lastPointerX, y: lastPointerY }),
    getLastPointerModifiers: () => lastPointerModifiers,
    getLastInteractivePointerHandle: () => lastInteractivePointerHandle,
    isActiveTextInputFocused: isActiveEditorFocused,
    isPointerInsideCanvas: () => pointerInsideCanvas,
    applyActiveTextDeletion,
    beginTouchTextFocusDeferral,
    cancelTouchTextFocusDeferral,
    commitTouchTextFocusDeferral,
    refocusActiveTextInput,
    resetAppSession,
    setCapturedPointerHandle: (handle: bigint | null) => {
      capturedPointerHandle = handle;
    },
    setLastPointerClientPosition: (x: number, y: number) => {
      lastPointerClientX = x;
      lastPointerClientY = y;
    },
    setLastPointerModifiers: (modifiers: number) => {
      lastPointerModifiers = modifiers;
    },
    setLastPointerPosition: (x: number, y: number) => {
      lastPointerX = x;
      lastPointerY = y;
    },
    setLastInteractivePointerHandle: (handle: bigint | null) => {
      lastInteractivePointerHandle = handle;
    },
    setPointerInsideCanvas: (flag: boolean) => {
      pointerInsideCanvas = flag;
    },
  };
}
